INSERT INTO "ecc_domains" ("code", "name_ar", "name_en", "sort") VALUES
  ('1', 'حوكمة الأمن السيبراني', 'Cybersecurity Governance', 1),
  ('2', 'تعزيز الأمن السيبراني', 'Cybersecurity Defense', 2),
  ('3', 'صمود الأمن السيبراني', 'Cybersecurity Resilience', 3),
  ('4', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية', 'Third-Party and Cloud Computing Cybersecurity', 4);
INSERT INTO "ecc_subdomains" ("code", "domain_code", "name_ar", "name_en", "objective_ar", "sort") VALUES
  ('1-1', '1', 'إستراتيجية الأمن السيبراني', 'Cybersecurity Strategy', 'ضمان إسهام خطط العمل للأمن السيبراني والأهداف والمبادرات والمشاريع داخل الجهة في تحقيق المتطلبات التشريعية والتنظيمية ذات العلاقة.', 1),
  ('1-2', '1', 'إدارة الأمن السيبراني', 'Cybersecurity Management', 'ضمان التزام ودعم صاحب الصلاحية للجهة فيما يتعلق بإدارة وتطبيق برامج الأمن السيبراني في تلك الجهة وفقاً للمتطلبات التشريعية والتنظيمية ذات العلاقة.', 2),
  ('1-3', '1', 'سياسات وإجراءات الأمن السيبراني', 'Cybersecurity Policies and Procedures', 'ضمان توثيق ونشر متطلبات الأمن السيبراني والتزام الجهة بها، وذلك وفقاً لمتطلبات الأعمال التنظيمية للجهة، والمتطلبات التشريعية والتنظيمية ذات العلاقة.', 3),
  ('1-4', '1', 'أدوار ومسؤوليات الأمن السيبراني', 'Cybersecurity Roles and Responsibilities', 'ضمان تحديد أدوار ومسؤوليات واضحة لجميع الأطراف المشاركة في تطبيق ضوابط الأمن السيبراني في الجهة.', 4),
  ('1-5', '1', 'إدارة مخاطر الأمن السيبراني', 'Cybersecurity Risk Management', 'ضمان إدارة مخاطر الأمن السيبراني على نحو ممنهج يهدف إلى حماية الأصول المعلوماتية والتقنية للجهة، وذلك وفقاً للسياسات والإجراءات التنظيمية للجهة والمتطلبات التشريعية والتنظيمية ذات العلاقة.', 5),
  ('1-6', '1', 'الأمن السيبراني ضمن إدارة المشاريع المعلوماتية والتقنية', 'Cybersecurity in Information Technology Projects', 'التأكد من أن متطلبات الأمن السيبراني مضمنة في منهجية وإجراءات إدارة مشاريع الجهة لحماية السرية وسلامة الأصول المعلوماتية والتقنية للجهة ودقتها وتوافرها، وذلك وفقاً للسياسات والإجراءات التنظيمية للجهة والمتطلبات التشريعية والتنظيمية ذات العلاقة.', 6),
  ('1-7', '1', 'الالتزام بتشريعات وتنظيمات ومعايير الأمن السيبراني', 'Cybersecurity Regulatory Compliance', 'ضمان التأكد من أن برنامج الأمن السيبراني لدى الجهة يتوافق مع المتطلبات التشريعية والتنظيمية ذات العلاقة.', 7),
  ('1-8', '1', 'المراجعة والتدقيق الدوري للأمن السيبراني', 'Cybersecurity Periodical Assessment and Audit', 'ضمان التأكد من أن ضوابط الأمن السيبراني لدى الجهة مطبقة وتعمل وفقاً للسياسات والإجراءات التنظيمية للجهة، والمتطلبات التشريعية والتنظيمية الوطنية ذات العلاقة، والمتطلبات الدولية المقرّة تنظيمياً على الجهة.', 8),
  ('1-9', '1', 'الأمن السيبراني المتعلق بالموارد البشرية', 'Cybersecurity in Human Resources', 'ضمان التأكد من أن مخاطر ومتطلبات الأمن السيبراني المتعلقة بالعاملين (موظفين ومتعاقدين) في الجهة تعالج بفعالية قبل وأثناء وعند انتهاء/إنهاء عملهم، وذلك وفقاً للسياسات والإجراءات التنظيمية للجهة، والمتطلبات التشريعية والتنظيمية ذات العلاقة.', 9),
  ('1-10', '1', 'برنامج التوعية والتدريب بالأمن السيبراني', 'Cybersecurity Awareness and Training Program', 'ضمان التأكد من أن العاملين بالجهة لديهم التوعية الأمنية اللازمة وعلى دراية بمسؤولياتهم في مجال الأمن السيبراني. والتأكد من تزويد العاملين بالجهة بالمهارات والمؤهلات والدورات التدريبية المطلوبة في مجال الأمن السيبراني لحماية الأصول المعلوماتية والتقنية للجهة والقيام بمسؤولياتهم تجاه الأمن السيبراني.', 10),
  ('2-1', '2', 'إدارة الأصول', 'Asset Management', 'للتأكد من أن الجهة لديها قائمة جرد دقيقة وحديثة للأصول تشمل التفاصيل ذات العلاقة لجميع الأصول المعلوماتية والتقنية المتاحة للجهة، من أجل دعم العمليات التشغيلية للجهة ومتطلبات الأمن السيبراني، لتحقيق سرية وسلامة الأصول المعلوماتية والتقنية للجهة ودقتها وتوافرها.', 11),
  ('2-2', '2', 'إدارة هويات الدخول والصلاحيات', 'Identity and Access Management', 'ضمان حماية الأمن السيبراني للوصول المنطقي (Logical Access) إلى الأصول المعلوماتية والتقنية للجهة من أجل منع الوصول غير المصرح به وتقييد الوصول إلى ما هو مطلوب لإنجاز الأعمال المتعلقة بالجهة.', 12),
  ('2-3', '2', 'حماية الأنظمة وأجهزة معالجة المعلومات', 'Information System and Processing Facilities Protection', 'ضمان حماية الأنظمة وأجهزة معالجة المعلومات بما في ذلك أجهزة المستخدمين والبنى التحتية للجهة من المخاطر السيبرانية.', 13),
  ('2-4', '2', 'حماية البريد الإلكتروني', 'Email Protection', 'ضمان حماية البريد الإلكتروني للجهة من المخاطر السيبرانية.', 14),
  ('2-5', '2', 'إدارة أمن الشبكات', 'Networks Security Management', 'ضمان حماية شبكات الجهة من المخاطر السيبرانية.', 15),
  ('2-6', '2', 'أمن الأجهزة المحمولة', 'Mobile Devices Security', 'ضمان حماية أجهزة الجهة المحمولة (بما في ذلك أجهزة الحاسب المحمول والهواتف الذكية والأجهزة الذكية اللوحية) من المخاطر السيبرانية. وضمان التعامل بشكل آمن مع المعلومات الحساسة والمعلومات الخاصة بأعمال الجهة وحمايتها أثناء النقل والتخزين عند استخدام الأجهزة الشخصية للعاملين في الجهة (مبدأ "BYOD").', 16),
  ('2-7', '2', 'حماية البيانات والمعلومات', 'Data and Information Protection', 'ضمان حماية السرية وسلامة بيانات ومعلومات الجهة ودقتها وتوافرها، وذلك وفقاً للسياسات والإجراءات التنظيمية للجهة، والمتطلبات التشريعية والتنظيمية ذات العلاقة.', 17),
  ('2-8', '2', 'التشفير', 'Cryptography', 'ضمان الاستخدام السليم والفعال للتشفير لحماية الأصول المعلوماتية الإلكترونية للجهة، وذلك وفقاً للمعايير الوطنية للتشفير الصادرة من الهيئة، وللسياسات والإجراءات التنظيمية للجهة، وبناء على تقييم المخاطر، وبحسب المتطلبات التشريعية والتنظيمية ذات العلاقة.', 18),
  ('2-9', '2', 'إدارة النسخ الاحتياطية', 'Backup and Recovery Management', 'ضمان حماية بيانات ومعلومات الجهة والإعدادات التقنية للأنظمة والتطبيقات الخاصة بالجهة من الأضرار الناجمة عن المخاطر السيبرانية، وذلك وفقاً للسياسات والإجراءات التنظيمية للجهة، والمتطلبات التشريعية والتنظيمية ذات العلاقة.', 19),
  ('2-10', '2', 'إدارة الثغرات', 'Vulnerabilities Management', 'ضمان اكتشاف الثغرات التقنية في الوقت المناسب ومعالجتها بشكل فعال، وذلك لمنع أو تقليل احتمالية استغلال هذه الثغرات من قبل الهجمات السيبرانية وتقليل الآثار المترتبة على أعمال الجهة.', 20),
  ('2-11', '2', 'اختبار الاختراق', 'Penetration Testing', 'تقييم واختبار مدى فعالية قدرات تعزيز الأمن السيبراني في الجهة، وذلك من خلال عمل محاكاة لتقنيات وأساليب الهجوم السيبراني الفعلية. ولاكتشاف نقاط الضعف الأمنية غير المعروفة والتي قد تؤدي إلى الاختراق السيبراني للجهة. وذلك وفقاً للمتطلبات التشريعية والتنظيمية ذات العلاقة.', 21),
  ('2-12', '2', 'إدارة سجلات الأحداث ومراقبة الأمن السيبراني', 'Cybersecurity Event Logs and Monitoring Management', 'ضمان تجميع وتحليل ومراقبة سجلات أحداث الأمن السيبراني في الوقت المناسب من أجل الاكتشاف الاستباقي للهجمات السيبرانية وإدارة مخاطرها بفعالية لمنع أو تقليل الآثار المترتبة على أعمال الجهة.', 22),
  ('2-13', '2', 'إدارة حوادث وتهديدات الأمن السيبراني', 'Cybersecurity Incident and Threat Management', 'ضمان تحديد واكتشاف حوادث الأمن السيبراني في الوقت المناسب وإدارتها بشكل فعّال والتعامل مع تهديدات الأمن السيبراني استباقياً من أجل منع أو تقليل الآثار المترتبة على أعمال الجهة. مع مراعاة ما ورد في الأمر السامي الكريم رقم 37140 وتاريخ 14 / 8 / 1438 هـ.', 23),
  ('2-14', '2', 'الأمن المادي', 'Physical Security', 'ضمان حماية الأصول المعلوماتية والتقنية للجهة من الوصول المادي غير المصرح به والفقدان والسرقة والتخريب.', 24),
  ('2-15', '2', 'حماية تطبيقات الويب', 'Web Application Security', 'ضمان حماية تطبيقات الويب الخارجية للجهة من المخاطر السيبرانية.', 25),
  ('3-1', '3', 'جوانب صمود الأمن السيبراني في إدارة استمرارية الأعمال', 'Cybersecurity Resilience aspects of Business Continuity Management (BCM)', 'ضمان توافر متطلبات صمود الأمن السيبراني في إدارة استمرارية أعمال الجهة. وضمان معالجة وتقليل الآثار المترتبة على الاضطرابات في الخدمات الإلكترونية الحرجة للجهة وأنظمة وأجهزة معالجة معلوماتها جراء الكوارث الناتجة عن المخاطر السيبرانية.', 26),
  ('4-1', '4', 'الأمن السيبراني المتعلق بالأطراف الخارجية', 'Third-Party Cybersecurity', 'ضمان حماية أصول الجهة من مخاطر الأمن السيبراني المتعلقة بالأطراف الخارجية (بما في ذلك خدمات الإسناد للأمن السيبراني أو لتقنية المعلومات "Outsourcing" والخدمات المدارة "Managed Services"). وفقاً للسياسات والإجراءات التنظيمية للجهة، والمتطلبات التشريعية والتنظيمية ذات العلاقة.', 27),
  ('4-2', '4', 'الأمن السيبراني المتعلق بالحوسبة السحابية والاستضافة', 'Cloud Computing and Hosting Cybersecurity', 'ضمان معالجة المخاطر السيبرانية وتنفيذ متطلبات الأمن السيبراني للحوسبة السحابية والاستضافة بشكل ملائم وفعّال، وذلك وفقاً للسياسات والإجراءات التنظيمية للجهة، والمتطلبات التشريعية والتنظيمية والأوامر والقرارات ذات العلاقة. وضمان حماية الأصول المعلوماتية والتقنية للجهة على خدمات الحوسبة السحابية التي تتم استضافتها أو معالجتها أو إدارتها بواسطة أطراف خارجية.', 28);
INSERT INTO "ecc_controls" ("code", "subdomain_code", "parent_code", "text_ar", "sort") VALUES
  ('1-1-1', '1-1', NULL, 'يجب تحديد وتوثيق واعتماد إستراتيجية الأمن السيبراني للجهة ودعمها من قبل رئيس الجهة أو من ينيبه (ويشار له في هذه الضوابط باسم "صاحب الصلاحية")، وأن تتماشى الأهداف الإستراتيجية للأمن السيبراني للجهة مع المتطلبات التشريعية والتنظيمية ذات العلاقة.', 1),
  ('1-1-2', '1-1', NULL, 'يجب العمل على تنفيذ خطة عمل لتطبيق إستراتيجية الأمن السيبراني من قبل الجهة.', 2),
  ('1-1-3', '1-1', NULL, 'يجب مراجعة إستراتيجية الأمن السيبراني على فترات زمنية مخطط لها (أو في حالة حدوث تغييرات في المتطلبات التشريعية والتنظيمية ذات العلاقة).', 3),
  ('1-2-1', '1-2', NULL, 'يجب إنشاء إدارة معنية بالأمن السيبراني في الجهة مستقلة عن إدارة تقنية المعلومات والاتصالات (ICT/ IT) (وفقاً للأمر السامي الكريم رقم 37140 وتاريخ 14 / 8 / 1438 هـ). ويفضل ارتباطها مباشرة برئيس الجهة أو من ينيبه، مع الأخذ بالاعتبار عدم تعارض المصالح.', 4),
  ('1-2-2', '1-2', NULL, 'يجب شغل جميع وظائف الأمن السيبراني من قبل مواطنين متفرغين وذوي كفاءة في مجال الأمن السيبراني.', 5),
  ('1-2-3', '1-2', NULL, 'يجب إنشاء لجنة إشرافية للأمن السيبراني بتوجيه من صاحب الصلاحية للجهة لضمان التزام ودعم ومتابعة تطبيق برامج وتشريعات الأمن السيبراني، ويتم تحديد وتوثيق واعتماد أعضاء اللجنة ومسؤولياتها وإطار حوكمة أعمالها على أن يكون رئيس الإدارة المعنية بالأمن السيبراني أحد أعضائها. ويفضل ارتباطها مباشرة برئيس الجهة أو من ينيبه، مع الأخذ بالاعتبار عدم تعارض المصالح.', 6),
  ('1-3-1', '1-3', NULL, 'يجب على الإدارة المعنية بالأمن السيبراني في الجهة تحديد سياسات وإجراءات الأمن السيبراني وما تشمله من ضوابط ومتطلبات الأمن السيبراني، وتوثيقها واعتمادها من قبل صاحب الصلاحية في الجهة، كما يجب نشرها إلى ذوي العلاقة من العاملين في الجهة والأطراف المعنية بها.', 7),
  ('1-3-2', '1-3', NULL, 'يجب على الإدارة المعنية بالأمن السيبراني ضمان تطبيق سياسات وإجراءات الأمن السيبراني في الجهة وما تشمله من ضوابط ومتطلبات.', 8),
  ('1-3-3', '1-3', NULL, 'يجب أن تكون سياسات وإجراءات الأمن السيبراني مدعومة بمعايير تقنية أمنية (على سبيل المثال: المعايير التقنية الأمنية لجدار الحماية وقواعد البيانات، وأنظمة التشغيل، إلخ).', 9),
  ('1-3-4', '1-3', NULL, 'يجب مراجعة سياسات وإجراءات ومعايير الأمن السيبراني وتحديثها على فترات زمنية مخطط لها (أو في حالة حدوث تغييرات في المتطلبات التشريعية والتنظيمية والمعايير ذات العلاقة)، كما يجب توثيق التغييرات واعتمادها.', 10),
  ('1-4-1', '1-4', NULL, 'يجب على صاحب الصلاحية تحديد وتوثيق واعتماد الهيكل التنظيمي للحوكمة والأدوار والمسؤوليات الخاصة بالأمن السيبراني للجهة، وتكليف الأشخاص المعنيين بها، كما يجب تقديم الدعم اللازم لإنفاذ ذلك، مع الأخذ بالاعتبار عدم تعارض المصالح.', 11),
  ('1-4-2', '1-4', NULL, 'يجب مراجعة أدوار ومسؤوليات الأمن السيبراني في الجهة وتحديثها على فترات زمنية مخطط لها (أو في حالة حدوث تغييرات في المتطلبات التشريعية والتنظيمية ذات العلاقة).', 12),
  ('1-5-1', '1-5', NULL, 'يجب على الإدارة المعنية بالأمن السيبراني في الجهة تحديد وتوثيق واعتماد منهجية وإجراءات إدارة مخاطر الأمن السيبراني في الجهة. وذلك وفقاً لاعتبارات السرية وتوافر وسلامة الأصول المعلوماتية والتقنية.', 13),
  ('1-5-2', '1-5', NULL, 'يجب على الإدارة المعنية بالأمن السيبراني تطبيق منهجية وإجراءات إدارة مخاطر الأمن السيبراني في الجهة.', 14),
  ('1-5-3', '1-5', NULL, 'يجب تنفيذ إجراءات تقييم مخاطر الأمن السيبراني بحد أدنى في الحالات التالية:', 15),
  ('1-5-3-1', '1-5', '1-5-3', 'في مرحلة مبكرة من المشاريع التقنية.', 16),
  ('1-5-3-2', '1-5', '1-5-3', 'قبل إجراء تغيير جوهري في البنية التقنية.', 17),
  ('1-5-3-3', '1-5', '1-5-3', 'عند التخطيط للحصول على خدمات طرف خارجي.', 18),
  ('1-5-3-4', '1-5', '1-5-3', 'عند التخطيط وقبل إطلاق منتجات وخدمات تقنية جديدة.', 19),
  ('1-5-4', '1-5', NULL, 'يجب مراجعة منهجية وإجراءات إدارة مخاطر الأمن السيبراني وتحديثها على فترات زمنية مخطط لها (أو في حالة حدوث تغييرات في المتطلبات التشريعية والتنظيمية والمعايير ذات العلاقة)، كما يجب توثيق التغييرات واعتمادها.', 20),
  ('1-6-1', '1-6', NULL, 'يجب تضمين متطلبات الأمن السيبراني في منهجية وإجراءات إدارة المشاريع وفي إدارة التغيير على الأصول المعلوماتية والتقنية في الجهة لضمان تحديد مخاطر الأمن السيبراني ومعالجتها كجزء من دورة حياة المشروع التقني، وأن تكون متطلبات الأمن السيبراني جزء أساسي من متطلبات المشاريع التقنية.', 21),
  ('1-6-2', '1-6', NULL, 'يجب أن تغطي متطلبات الأمن السيبراني لإدارة المشاريع والتغييرات على الأصول المعلوماتية والتقنية للجهة بحد أدنى ما يلي:', 22),
  ('1-6-2-1', '1-6', '1-6-2', 'تقييم الثغرات ومعالجتها.', 23),
  ('1-6-2-2', '1-6', '1-6-2', 'إجراء مراجعة للإعدادات والتحصين (Secure Configuration and Hardening) وحزم التحديثات قبل إطلاق وتدشين المشاريع والتغييرات.', 24),
  ('1-6-3', '1-6', NULL, 'يجب أن تغطي متطلبات الأمن السيبراني لمشاريع تطوير التطبيقات والبرمجيات الخاصة للجهة بحد أدنى ما يلي:', 25),
  ('1-6-3-1', '1-6', '1-6-3', 'استخدام معايير التطوير الآمن للتطبيقات (Secure Coding Standards).', 26),
  ('1-6-3-2', '1-6', '1-6-3', 'استخدام مصادر مرخصة وموثوقة لأدوات تطوير التطبيقات والمكتبات الخاصة بها (Libraries).', 27),
  ('1-6-3-3', '1-6', '1-6-3', 'إجراء اختبار للتحقق من مدى استيفاء التطبيقات للمتطلبات الأمنية السيبرانية للجهة.', 28),
  ('1-6-3-4', '1-6', '1-6-3', 'أمن التكامل (Integration) بين التطبيقات.', 29),
  ('1-6-3-5', '1-6', '1-6-3', 'إجراء مراجعة للإعدادات والتحصين (Secure Configuration and Hardening) وحزم التحديثات قبل إطلاق وتدشين التطبيقات.', 30),
  ('1-6-4', '1-6', NULL, 'يجب مراجعة متطلبات الأمن السيبراني في إدارة المشاريع في الجهة دورياً.', 31),
  ('1-7-1', '1-7', NULL, 'في حال وجود اتفاقيات أو التزامات دولية معتمدة محلياً تتضمن متطلبات خاصة بالأمن السيبراني، فيجب على الجهة حصر تلك المتطلبات والالتزام بها.', 32),
  ('1-8-1', '1-8', NULL, 'يجب على الإدارة المعنية بالأمن السيبراني في الجهة مراجعة تطبيق ضوابط الأمن السيبراني دورياً.', 33),
  ('1-8-2', '1-8', NULL, 'يجب مراجعة وتدقيق تطبيق ضوابط الأمن السيبراني في الجهة، من قبل أطراف مستقلة عن الإدارة المعنية بالأمن السيبراني (مثل الإدارة المعنية بالمراجعة في الجهة). على أن تتم المراجعة والتدقيق بشكل مستقل يراعى فيه مبدأ عدم تعارض المصالح، وذلك وفقاً للمعايير العامة المقبولة للمراجعة والتدقيق والمتطلبات التشريعية والتنظيمية ذات العلاقة.', 34),
  ('1-8-3', '1-8', NULL, 'يجب توثيق نتائج مراجعة وتدقيق الأمن السيبراني، وعرضها على اللجنة الإشرافية للأمن السيبراني وصاحب الصلاحية. كما يجب أن تشتمل النتائج على نطاق المراجعة والتدقيق، والملاحظات المكتشفة، والتوصيات والإجراءات التصحيحية، وخطة معالجة الملاحظات.', 35),
  ('1-9-1', '1-9', NULL, 'يجب تحديد وتوثيق واعتماد متطلبات الأمن السيبراني المتعلقة بالعاملين قبل توظيفهم وأثناء عملهم وعند انتهاء/إنهاء عملهم في الجهة.', 36),
  ('1-9-2', '1-9', NULL, 'يجب تطبيق متطلبات الأمن السيبراني المتعلقة بالعاملين في الجهة.', 37),
  ('1-9-3', '1-9', NULL, 'يجب أن تغطي متطلبات الأمن السيبراني قبل بدء علاقة العاملين المهنية بالجهة بحد أدنى ما يلي:', 38),
  ('1-9-3-1', '1-9', '1-9-3', 'تضمين مسؤوليات الأمن السيبراني وبنود المحافظة على سرية المعلومات (Non-Disclosure Clauses) في عقود العاملين في الجهة (لتشمل خلال وبعد انتهاء/إنهاء العلاقة الوظيفية مع الجهة).', 39),
  ('1-9-3-2', '1-9', '1-9-3', 'إجراء المسح الأمني (Screening or Vetting) للعاملين في وظائف الأمن السيبراني والوظائف التقنية ذات الصلاحيات الهامة والحساسة.', 40),
  ('1-9-4', '1-9', NULL, 'يجب أن تغطي متطلبات الأمن السيبراني خلال علاقة العاملين المهنية بالجهة بحد أدنى ما يلي:', 41),
  ('1-9-4-1', '1-9', '1-9-4', 'التوعية بالأمن السيبراني (عند بداية المهنة الوظيفية وخلالها).', 42),
  ('1-9-4-2', '1-9', '1-9-4', 'تطبيق متطلبات الأمن السيبراني والالتزام بها وفقاً لسياسات وإجراءات وعمليات الأمن السيبراني للجهة.', 43),
  ('1-9-5', '1-9', NULL, 'يجب مراجعة وإلغاء الصلاحيات للعاملين مباشرة بعد انتهاء/إنهاء العلاقة الوظيفية مع الجهة.', 44),
  ('1-9-6', '1-9', NULL, 'يجب مراجعة متطلبات الأمن السيبراني المتعلقة بالعاملين في الجهة دورياً.', 45),
  ('1-10-1', '1-10', NULL, 'يجب تطوير واعتماد برنامج للتوعية بالأمن السيبراني في الجهة من خلال قنوات متعددة دورياً، وذلك لتعزيز الوعي بالأمن السيبراني وتهديداته ومخاطره، وبناء ثقافة إيجابية للأمن السيبراني.', 46),
  ('1-10-2', '1-10', NULL, 'يجب تطبيق البرنامج المعتمد للتوعية بالأمن السيبراني في الجهة.', 47),
  ('1-10-3', '1-10', NULL, 'يجب أن يغطي برنامج التوعية بالأمن السيبراني كيفية حماية الجهة من أهم المخاطر والتهديدات السيبرانية وما يستجد منها، بما في ذلك:', 48),
  ('1-10-3-1', '1-10', '1-10-3', 'التعامل الآمن مع خدمات البريد الإلكتروني خصوصاً مع رسائل التصيد الإلكتروني.', 49),
  ('1-10-3-2', '1-10', '1-10-3', 'التعامل الآمن مع الأجهزة المحمولة ووسائط التخزين.', 50),
  ('1-10-3-3', '1-10', '1-10-3', 'التعامل الآمن مع خدمات تصفح الإنترنت.', 51),
  ('1-10-3-4', '1-10', '1-10-3', 'التعامل الآمن مع وسائل التواصل الاجتماعي.', 52),
  ('1-10-4', '1-10', NULL, 'يجب توفير المهارات المتخصصة والتدريب اللازم للعاملين في المجالات الوظيفية ذات العلاقة المباشرة بالأمن السيبراني في الجهة، وتصنيفها بما يتماشى مع مسؤولياتهم الوظيفية فيما يتعلق بالأمن السيبراني، بما في ذلك:', 53),
  ('1-10-4-1', '1-10', '1-10-4', 'موظفو الإدارة المعنية بالأمن السيبراني.', 54),
  ('1-10-4-2', '1-10', '1-10-4', 'الموظفون العاملون في تطوير البرامج والتطبيقات والموظفون المشغلون للأصول المعلوماتية والتقنية للجهة.', 55),
  ('1-10-4-3', '1-10', '1-10-4', 'الوظائف الإشرافية والتنفيذية.', 56),
  ('1-10-5', '1-10', NULL, 'يجب مراجعة تطبيق برنامج التوعية بالأمن السيبراني في الجهة دورياً.', 57),
  ('2-1-1', '2-1', NULL, 'يجب تحديد وتوثيق واعتماد متطلبات الأمن السيبراني لإدارة الأصول المعلوماتية والتقنية للجهة.', 58),
  ('2-1-2', '2-1', NULL, 'يجب تطبيق متطلبات الأمن السيبراني لإدارة الأصول المعلوماتية والتقنية للجهة.', 59),
  ('2-1-3', '2-1', NULL, 'يجب تحديد وتوثيق واعتماد ونشر سياسة الاستخدام المقبول للأصول المعلوماتية والتقنية للجهة.', 60),
  ('2-1-4', '2-1', NULL, 'يجب تطبيق سياسة الاستخدام المقبول للأصول المعلوماتية والتقنية للجهة.', 61),
  ('2-1-5', '2-1', NULL, 'يجب تصنيف الأصول المعلوماتية والتقنية للجهة وترميزها (Labeling) والتعامل معها وفقاً للمتطلبات التشريعية والتنظيمية ذات العلاقة.', 62),
  ('2-1-6', '2-1', NULL, 'يجب مراجعة متطلبات الأمن السيبراني لإدارة الأصول المعلوماتية والتقنية للجهة دورياً.', 63),
  ('2-2-1', '2-2', NULL, 'يجب تحديد وتوثيق واعتماد متطلبات الأمن السيبراني لإدارة هويات الدخول والصلاحيات في الجهة.', 64),
  ('2-2-2', '2-2', NULL, 'يجب تطبيق متطلبات الأمن السيبراني لإدارة هويات الدخول والصلاحيات في الجهة.', 65),
  ('2-2-3', '2-2', NULL, 'يجب أن تغطي متطلبات الأمن السيبراني المتعلقة بإدارة هويات الدخول والصلاحيات في الجهة بحد أدنى ما يلي:', 66),
  ('2-2-3-1', '2-2', '2-2-3', 'التحقق من الهوية أحادي العنصر (Single-factor authentication) بناءً على إدارة تسجيل المستخدم، وإدارة كلمة المرور.', 67),
  ('2-2-3-2', '2-2', '2-2-3', 'التحقق من الهوية متعدد العناصر (Multi-Factor Authentication) وتحديد عناصر التحقق المناسبة وعددها وكذلك تقنيات التحقق المناسبة بناء على نتائج تقييم الأثر المحتمل لفشل عملية التحقق وتخطيها، وذلك لعمليات الدخول عن بعد والحسابات ذات الصلاحيات الهامة والحساسة.', 68),
  ('2-2-3-3', '2-2', '2-2-3', 'إدارة تصاريح وصلاحيات المستخدمين (Authorization) بناءً على مبادئ التحكم بالدخول والصلاحيات (مبدأ الحاجة إلى المعرفة والاستخدام "Need-to-know and Need-to-use"، ومبدأ الحد الأدنى من الصلاحيات والامتيازات "Least Privilege"، ومبدأ فصل المهام "Segregation of Duties").', 69),
  ('2-2-3-4', '2-2', '2-2-3', 'إدارة الصلاحيات الهامة والحساسة (Privileged Access Management).', 70),
  ('2-2-3-5', '2-2', '2-2-3', 'المراجعة الدورية لهويات الدخول والصلاحيات.', 71),
  ('2-2-4', '2-2', NULL, 'يجب مراجعة تطبيق متطلبات الأمن السيبراني لإدارة هويات الدخول والصلاحيات في الجهة دورياً.', 72),
  ('2-3-1', '2-3', NULL, 'يجب تحديد وتوثيق واعتماد متطلبات الأمن السيبراني لحماية الأنظمة وأجهزة معالجة المعلومات للجهة.', 73),
  ('2-3-2', '2-3', NULL, 'يجب تطبيق متطلبات الأمن السيبراني لحماية الأنظمة وأجهزة معالجة المعلومات للجهة.', 74),
  ('2-3-3', '2-3', NULL, 'يجب أن تغطي متطلبات الأمن السيبراني لحماية الأنظمة وأجهزة معالجة المعلومات للجهة بحد أدنى ما يلي:', 75),
  ('2-3-3-1', '2-3', '2-3-3', 'الحماية من الفيروسات والبرامج والأنشطة المشبوهة والبرمجيات الضارة (Malware) على أجهزة المستخدمين والخوادم باستخدام تقنيات وآليات الحماية الحديثة والمتقدمة، وإدارتها بشكل آمن.', 76),
  ('2-3-3-2', '2-3', '2-3-3', 'التقييد الحازم لاستخدام أجهزة وسائط التخزين الخارجية والأمن المتعلق بها.', 77),
  ('2-3-3-3', '2-3', '2-3-3', 'إدارة حزم التحديثات والإصلاحات للأنظمة والتطبيقات والأجهزة (Patch Management).', 78),
  ('2-3-3-4', '2-3', '2-3-3', 'مزامنة التوقيت (Clock Synchronization) مركزياً ومن مصدر دقيق وموثوق، ومن هذه المصادر ما توفره الهيئة السعودية للمواصفات والمقاييس والجودة.', 79),
  ('2-3-4', '2-3', NULL, 'يجب مراجعة متطلبات الأمن السيبراني لحماية الأنظمة وأجهزة معالجة المعلومات للجهة دورياً.', 80),
  ('2-4-1', '2-4', NULL, 'يجب تحديد وتوثيق واعتماد متطلبات الأمن السيبراني لحماية البريد الإلكتروني للجهة.', 81),
  ('2-4-2', '2-4', NULL, 'يجب تطبيق متطلبات الأمن السيبراني لحماية البريد الإلكتروني للجهة.', 82),
  ('2-4-3', '2-4', NULL, 'يجب أن تغطي متطلبات الأمن السيبراني لحماية البريد الإلكتروني للجهة بحد أدنى ما يلي:', 83),
  ('2-4-3-1', '2-4', '2-4-3', 'تحليل وتصفية (Filtering) رسائل البريد الإلكتروني (وخصوصاً رسائل التصيّد الإلكتروني "Phishing Emails" والرسائل الإقتحامية "Spam Emails") باستخدام تقنيات وآليات الحماية الحديثة والمتقدمة للبريد الإلكتروني.', 84),
  ('2-4-3-2', '2-4', '2-4-3', 'التحقق من الهوية متعدد العناصر (Multi-Factor Authentication) وتحديد عناصر التحقق المناسبة وعددها وكذلك تقنيات التحقق المناسبة بناء على نتائج تقييم الأثر المحتمل لفشل عملية التحقق وتخطيها، وذلك للدخول عن بعد والدخول عن طريق صفحة موقع البريد الإلكتروني (Webmail).', 85),
  ('2-4-3-3', '2-4', '2-4-3', 'النسخ الاحتياطي والأرشفة للبريد الإلكتروني.', 86),
  ('2-4-3-4', '2-4', '2-4-3', 'الحماية من التهديدات المتقدمة المستمرة (APT Protection)، التي تستخدم عادة الفيروسات والبرمجيات الضارة غير المعروفة مسبقاً (Zero-Day Malware)، وإدارتها بشكل آمن.', 87),
  ('2-4-3-5', '2-4', '2-4-3', 'توثيق مجال البريد الإلكتروني للجهة باستخدام إطار سياسة المرسل (Sender Policy Framework "SPF") والبريد المعرّف بمفاتيح النطاق (Domain Keys Identified Mail "DKIM") وسياسة مصادقة الرسائل والإبلاغ عنها (Domain Message Authentication Reporting and Conformance "DMARC").', 88),
  ('2-4-4', '2-4', NULL, 'يجب مراجعة تطبيق متطلبات الأمن السيبراني الخاصة بحماية البريد الإلكتروني للجهة دورياً.', 89),
  ('2-5-1', '2-5', NULL, 'يجب تحديد وتوثيق واعتماد متطلبات الأمن السيبراني لإدارة أمن شبكات الجهة.', 90),
  ('2-5-2', '2-5', NULL, 'يجب تطبيق متطلبات الأمن السيبراني لإدارة أمن شبكات الجهة.', 91),
  ('2-5-3', '2-5', NULL, 'يجب أن تغطي متطلبات الأمن السيبراني لإدارة أمن شبكات الجهة بحد أدنى ما يلي:', 92),
  ('2-5-3-1', '2-5', '2-5-3', 'العزل والتقسيم المادي أو المنطقي لأجزاء الشبكات بشكل آمن، واللازم للسيطرة على مخاطر الأمن السيبراني ذات العلاقة، باستخدام جدار الحماية (Firewall) ومبدأ الدفاع الأمني متعدد المراحل (Defense-in-Depth).', 93),
  ('2-5-3-2', '2-5', '2-5-3', 'عزل شبكة بيئة الإنتاج عن شبكات بيئات التطوير والاختبار.', 94),
  ('2-5-3-3', '2-5', '2-5-3', 'أمن التصفح والاتصال بالإنترنت، ويشمل ذلك التقييد الحازم للمواقع الإلكترونية المشبوهة، ومواقع مشاركة وتخزين الملفات، ومواقع الدخول عن بعد.', 95),
  ('2-5-3-4', '2-5', '2-5-3', 'أمن الشبكات اللاسلكية وحمايتها باستخدام وسائل آمنة للتحقق من الهوية والتشفير، وعدم ربط الشبكات اللاسلكية بشبكة الجهة الداخلية إلا بناءً على دراسة متكاملة للمخاطر المترتبة على ذلك والتعامل معها بما يضمن حماية الأصول التقنية للجهة.', 96),
  ('2-5-3-5', '2-5', '2-5-3', 'قيود وإدارة منافذ وبروتوكولات وخدمات الشبكة.', 97),
  ('2-5-3-6', '2-5', '2-5-3', 'أنظمة الحماية المتقدمة لاكتشاف ومنع الاختراقات (Intrusion Prevention Systems).', 98),
  ('2-5-3-7', '2-5', '2-5-3', 'أمن نظام أسماء النطاقات (DNS).', 99),
  ('2-5-3-8', '2-5', '2-5-3', 'حماية قناة تصفح الإنترنت من التهديدات المتقدمة المستمرة (APT Protection)، التي تستخدم عادة الفيروسات والبرمجيات الضارة غير المعروفة مسبقاً (Zero-Day Malware)، وإدارتها بشكل آمن.', 100),
  ('2-5-3-9', '2-5', '2-5-3', 'الحماية من هجمات تعطيل الشبكات (Distributed Denial of Service Attack "DDoS") للحد من المخاطر السيبرانية الناتجة عن هجمات تعطيل الشبكات.', 101),
  ('2-5-4', '2-5', NULL, 'يجب مراجعة تطبيق متطلبات الأمن السيبراني لإدارة أمن شبكات الجهة دورياً.', 102),
  ('2-6-1', '2-6', NULL, 'يجب تحديد وتوثيق واعتماد متطلبات الأمن السيبراني الخاصة بأمن الأجهزة المحمولة والأجهزة الشخصية للعاملين (BYOD) عند ارتباطها بشبكة الجهة.', 103),
  ('2-6-2', '2-6', NULL, 'يجب تطبيق متطلبات الأمن السيبراني الخاصة بأمن الأجهزة المحمولة وأجهزة (BYOD) للجهة.', 104),
  ('2-6-3', '2-6', NULL, 'يجب أن تغطي متطلبات الأمن السيبراني الخاصة بأمن الأجهزة المحمولة وأجهزة (BYOD) للجهة بحد أدنى ما يلي:', 105),
  ('2-6-3-1', '2-6', '2-6-3', 'فصل وتشفير البيانات والمعلومات (الخاصة بالجهة) المخزنة على الأجهزة المحمولة وأجهزة (BYOD).', 106),
  ('2-6-3-2', '2-6', '2-6-3', 'الاستخدام المحدد والمقيد بناءً على ما تتطلبه مصلحة أعمال الجهة.', 107),
  ('2-6-3-3', '2-6', '2-6-3', 'حذف البيانات والمعلومات (الخاصة بالجهة) المخزنة على الأجهزة المحمولة وأجهزة (BYOD) عند فقدان الأجهزة أو بعد انتهاء/إنهاء العلاقة الوظيفية مع الجهة.', 108),
  ('2-6-3-4', '2-6', '2-6-3', 'التوعية الأمنية للمستخدمين.', 109),
